package com.bank.settle.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates every ordering of a distinct payment batch via backtracking.
public class PermutationService {
    private static final Logger log = Logger.getLogger(PermutationService.class.getName());

    public List<List<String>> allOrderings(List<String> payments) {
        List<List<String>> result = new ArrayList<>();
        boolean[] used = new boolean[payments.size()];
        backtrack(payments, used, new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " orderings");
        return result;
    }

    private void backtrack(List<String> payments, boolean[] used,
                           List<String> current, List<List<String>> result) {
        if (current.size() == payments.size()) {
            result.add(new ArrayList<>(current)); // defensive copy of a full ordering
            log.fine(() -> "Completed ordering " + current);
            return;
        }
        for (int i = 0; i < payments.size(); i++) {
            if (used[i]) {
                continue; // skip payments already placed
            }
            // choose
            used[i] = true;
            current.add(payments.get(i));
            // explore
            backtrack(payments, used, current, result);
            // un-choose (backtrack)
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}
